#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6) -- independent closed-form recomputation.

Written by the validator from the formulas as STATED in the version-4
specification text (definitions.A, instrument_value, reading_R_B, reading_R_M,
W, rho, d_star_of_m, frozen_c2_fixture) and Semaev 2015 Section 4.3 eq. (11).
It imports neither the frozen instrument nor any producer code block.
Arithmetic: exact integers / fractions.Fraction for k, m!, binomials and
r; mpmath 1.3.0 at 60 significant digits for exp, log.  Zero runs: no
curve, no solver, no field arithmetic.

Labels: KR in {MI1 (k = n/m unceiled), CEIL (k = ceil(n/m))};
        PF in {PF1 (P = x), PF2 (P = 1 - exp(-x))}, x = 2^(m k - n)/m!.
"""
import json, math, re, sys, hashlib
from fractions import Fraction
import mpmath as mp

mp.mp.dps = 60
LOG2 = mp.log(2)


def log2(v):
    return mp.log(v) / LOG2


def kval(n, m, kr):
    if kr == "MI1":
        return Fraction(n, m)
    if kr == "CEIL":
        return Fraction(-(-n // m))
    raise ValueError(kr)


def A(n, m, kr, pf):
    """A(n, m) = k - log2 P(n, m, m, k)."""
    k = kval(n, m, kr)
    e = m * k - n                      # exact, an integer-valued Fraction
    assert e.denominator == 1
    x = mp.mpf(2) ** int(e) / mp.mpf(math.factorial(m))
    if pf == "PF1":
        P = x
    elif pf == "PF2":
        P = -mp.expm1(-x)
    else:
        raise ValueError(pf)
    return mp.mpf(k.numerator) / k.denominator - log2(P)


def W(n, D):
    return log2(mp.mpf(sum(math.comb(n, d) for d in range(D + 1))))


def stage1(n, m, kr, pf, omega, solve=True):
    """block_n4w stage 1 at t = m: A + 4 omega log2 n (solve=False: absorbed)."""
    s = 4 * mp.mpf(omega) * log2(n) if solve else mp.mpf(0)
    return A(n, m, kr, pf) + s


def CI(n, omega, kr, pf, solve=True, m_hi=30, total=False, omega_prime=2):
    """First minimum (strict <, ascending m) over m in 2..min(m_hi, n)."""
    best = None
    vals = []
    for m in range(2, min(m_hi, n) + 1):
        v = stage1(n, m, kr, pf, omega, solve)
        if total:
            k = kval(n, m, kr)
            s2 = mp.mpf(k.numerator) / k.denominator * omega_prime
            v = log2(mp.mpf(2) ** v + mp.mpf(2) ** s2)
        vals.append((m, v))
        if best is None or v < best[1]:
            best = (m, v)
    rest = sorted([t for t in vals if t[0] != best[0]], key=lambda t: (t[1], t[0]))
    ru = rest[0]
    return {"value": best[1], "argmin": best[0], "runner_up": ru[0], "gap": ru[1] - best[1]}


def f(v, nd=10):
    return float(mp.nstr(v, nd + 6)) if not isinstance(v, (int, str)) else v


KRS = ["MI1", "CEIL"]
PFS = ["PF2", "PF1"]
out = {"library": {"python": sys.version.split()[0], "mpmath": mp.__version__, "mp_dps": mp.mp.dps}}

# ---------------------------------------------------------------- (i) A(571, m)
a571 = []
for m in range(2, 31):
    row = {"m": m}
    for kr in KRS:
        k = kval(571, m, kr)
        row[f"relation_store_log2_{kr}"] = f(mp.mpf(k.numerator) / k.denominator, 6)
        for pf in PFS:
            row[f"A_{kr}_{pf}"] = f(A(571, m, kr, pf), 10)
        row[f"PF2_minus_PF1_{kr}"] = f(A(571, m, kr, "PF2") - A(571, m, kr, "PF1"), 12)
    for pf in PFS:
        row[f"CEIL_minus_MI1_{pf}"] = f(A(571, m, "CEIL", pf) - A(571, m, "MI1", pf), 10)
    a571.append(row)
out["A_571_by_m"] = a571

summ = {}
for kr in KRS:
    d = [(r["m"], r[f"PF2_minus_PF1_{kr}"]) for r in a571]
    pos = [t for t in d if t[1] > 0]
    mx = max(d, key=lambda t: t[1]); mn = min(d, key=lambda t: t[1])
    # least m from which PF2-PF1 stays below 0.01 bit at every larger m
    least = None
    for i in range(len(d)):
        if all(t[1] < 0.01 for t in d[i:]):
            least = d[i][0]; break
    summ[kr] = {"count_positive": len(pos), "count_nonpositive": len(d) - len(pos),
                "largest": mx, "smallest": mn, "least_m_below_0.01_from_then_on": least}
for pf in PFS:
    d = [(r["m"], r[f"CEIL_minus_MI1_{pf}"]) for r in a571]
    summ[f"CEIL_minus_MI1_{pf}"] = {
        "negative": sum(1 for t in d if t[1] < 0), "zero": sum(1 for t in d if t[1] == 0),
        "positive": sum(1 for t in d if t[1] > 0),
        "most_negative": min(d, key=lambda t: t[1]), "least_negative": max(d, key=lambda t: t[1])}
out["A_571_summary"] = summ

# --------------------------------------------- (i) minimised stage-1 cost, 3 degrees
mi2 = {}
for n in (571, 283, 359):
    for kr in KRS:
        r = {}
        for pf in PFS:
            c = CI(n, 3.0, kr, pf)
            k = kval(n, c["argmin"], kr)
            r[pf] = {"C_I": f(c["value"], 10), "argmin": c["argmin"], "runner_up": c["runner_up"],
                     "gap": f(c["gap"], 8), "relation_store_log2": f(mp.mpf(k.numerator) / k.denominator, 6),
                     "MR_B_D4": f(4 * log2(n), 6), "MR_M_D4": f(W(n, 4), 6)}
        move = CI(n, 3.0, kr, "PF1")["value"] - CI(n, 3.0, kr, "PF2")["value"]
        r["move_PF1_minus_PF2"] = mp.nstr(move, 6)
        r["argmin_changes"] = r["PF1"]["argmin"] != r["PF2"]["argmin"]
        r["abs_move_exceeds_1e-9"] = bool(abs(move) > mp.mpf("1e-9"))
        mi2[f"{n}_{kr}"] = r
out["MI2_consequence"] = mi2

# ------------------------------------------------- MI-2 and MI-1 direction over claim-(A) grid
DEG = [79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]
lower = notlower = 0
eqcells = []; ce_b = ce_e = ce_a = 0
for n in DEG:
    for m in range(2, min(30, n) + 1):
        for kr in KRS:
            if A(n, m, kr, "PF1") < A(n, m, kr, "PF2"):
                lower += 1
            else:
                notlower += 1
        for pf in ("PF2",):
            c = stage1(n, m, "CEIL", pf, 3.0); u = stage1(n, m, "MI1", pf, 3.0)
            if c < u: ce_b += 1
            elif c == u: ce_e += 1; eqcells.append((n, m))
            else: ce_a += 1
deg_ceil_below = sum(1 for n in DEG if CI(n, 3.0, "CEIL", "PF2")["value"] < CI(n, 3.0, "MI1", "PF2")["value"])
out["MI2_direction"] = {"cells_per_k_reading": sum(min(30, n) - 1 for n in DEG),
                        "PF1_below_PF2": lower, "PF1_not_below_PF2": notlower}
out["MI1_direction_PF2"] = {"cells": ce_b + ce_e + ce_a, "ceiled_below": ce_b, "equal": ce_e,
                            "above": ce_a, "equal_cells": eqcells,
                            "degrees_with_ceiled_CI_below_MI1_CI": deg_ceil_below}
# per-degree ceiled-minus-MI1 move of C_I under PF2 (MI-1 disclosed consequence carried)
out["kreading_table_PF2"] = {}
for n in DEG:
    u = CI(n, 3.0, "MI1", "PF2"); c = CI(n, 3.0, "CEIL", "PF2")
    out["kreading_table_PF2"][n] = {"MI1": [f(u["value"], 8), u["argmin"]], "CEIL": [f(c["value"], 8), c["argmin"]],
                                    "move": f(c["value"] - u["value"], 8)}

# ------------------------------------------------------------- (ii) the fixture
TGT = {571: (Fraction(186307, 1000), 12), 283: (Fraction(147649, 1000), 9)}
TOL = Fraction(5, 10000)


def fixture(kr, pf, omega=3.0, solve=True, total=False, m_hi=30):
    res = {}
    ok_all = True
    for n, (tv, tm) in TGT.items():
        c = CI(n, omega, kr, pf, solve=solve, m_hi=m_hi, total=total)
        dist = abs(c["value"] - mp.mpf(tv.numerator) / tv.denominator)
        ok = bool(dist <= mp.mpf(TOL.numerator) / TOL.denominator and c["argmin"] == tm)
        ok_all &= ok
        res[n] = {"value": f(c["value"], 10), "argmin": c["argmin"], "target": float(tv), "target_argmin": tm,
                  "abs_distance": mp.nstr(dist, 8), "slack": mp.nstr(mp.mpf("5e-4") - dist, 8), "pass": ok}
    res["overall"] = "PASS" if ok_all else "FAIL"
    return res


fx = {}
for kr in KRS:
    for pf in PFS:
        fx[f"{kr}_{pf}"] = fixture(kr, pf)
out["fixture_as_frozen"] = fx

# false-PASS readings (must FAIL) under both P forms
fp = {}
for pf in PFS:
    fp[f"ceiled_{pf}"] = fixture("CEIL", pf)
    fp[f"cofactor_absorbed_MI1_{pf}"] = fixture("MI1", pf, solve=False)
    fp[f"cofactor_absorbed_CEIL_{pf}"] = fixture("CEIL", pf, solve=False)
    fp[f"omega_2.376_MI1_{pf}"] = fixture("MI1", pf, omega=2.376)
    fp[f"omega_2.376_CEIL_{pf}"] = fixture("CEIL", pf, omega=2.376)
    # extra wrong readings the plan does not list (V4B-8 false-PASS duty)
    fp[f"omega_2.0_MI1_{pf}"] = fixture("MI1", pf, omega=2.0)
    fp[f"omega_2.807_MI1_{pf}"] = fixture("MI1", pf, omega=2.807)
    fp[f"omega_2.99_MI1_{pf}"] = fixture("MI1", pf, omega=2.99)
    fp[f"omega_2.9999_MI1_{pf}"] = fixture("MI1", pf, omega=2.9999)
    fp[f"total_stage1_plus_stage2_MI1_{pf}"] = fixture("MI1", pf, total=True)
    fp[f"m_range_2_to_60_MI1_{pf}"] = fixture("MI1", pf, m_hi=60)
out["fixture_false_pass_readings"] = fp

# ---------------------------------------------- rho from FIPS 186-4 primary text
FIPS = "/home/user/crypto-autoresearcher/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"
lines = open(FIPS, encoding="utf-8").read().split("\n")


def read_n(start, stop):
    """Decimal digits of the 'n =' field on 1-based lines start..stop (inclusive).
    The range is chosen to hold the n field only; the first line must start with 'n ='."""
    seg = lines[start - 1:stop]
    assert seg[0].lstrip().startswith("n"), seg[0]
    seg[0] = seg[0].split("=", 1)[1]
    for s in seg:
        assert re.fullmatch(r"[0-9\s\\]*", s), s
    return int(re.sub(r"[^0-9]", "", "".join(seg)))


R = {"K-571": (read_n(7023, 7029), 4, 571, 571), "B-571": (read_n(7060, 7066), 2, 571, 1),
     "K-283": (read_n(6852, 6854), 4, 283, 283), "B-283": (read_n(6887, 6891), 2, 283, 1)}
rho = {}
for c, (r, h, n, kc) in R.items():
    tr = h * r - (2 ** n + 1)          # Hasse: tr^2 <= 4 * 2^n, exact integers
    rho[c] = {"r": str(r), "bits": r.bit_length(), "h": h, "k_c": kc, "hasse_ok": tr * tr <= 4 * 2 ** n,
              "is_probable_prime": bool(pow(3, r - 1, r) == 1 and pow(5, r - 1, r) == 1),
              "rho": 0.5 * (log2(mp.pi * r / (4 * kc)))}
    rho[c]["rho_f"] = f(rho[c]["rho"], 10)
out["rho"] = {c: {kk: vv for kk, vv in d.items() if kk != "rho"} for c, d in rho.items()}

# ------------------------------------------ threshold tables at 571, all four pairs
L571 = log2(571)


def SB(D, omega=3.0):
    return D * mp.mpf(omega) * L571


W4 = W(571, 4)
WD = {D: W(571, D) for D in range(2, 65)}


def SM(D, omega=3.0):
    return mp.mpf(omega) * (WD[D] - W4 + 4 * L571)


def dstar(Aval, rh, reading):
    S = SB if reading == "R-B" else SM
    for D in range(2, 65):
        if Aval + S(D) - rh > 0:
            return "D* <= 2" if D == 2 else D
    return "no crossing at D <= 64"


def tokval(t):
    return 2 if t == "D* <= 2" else (65 if t == "no crossing at D <= 64" else t)


tables = {}
for kr in KRS:
    for pf in PFS:
        tb = {}
        for c in ("K-571", "B-571"):
            for rd in ("R-B", "R-M"):
                for m in range(2, 31):
                    a = A(571, m, kr, pf)
                    tb[(c, rd, m)] = dstar(a, rho[c]["rho"], rd)
        tables[f"{kr}_{pf}"] = tb
dreal = {}
for kr in KRS:
    for pf in PFS:
        for c in ("K-571", "B-571"):
            for m in range(2, 31):
                dreal[(kr, pf, c, m)] = (rho[c]["rho"] - A(571, m, kr, pf)) / (3 * L571)

comp = {}
pairs = [("CEIL_PF2", "MI1_PF2"), ("MI1_PF1", "MI1_PF2"), ("CEIL_PF1", "MI1_PF2"), ("CEIL_PF1", "CEIL_PF2")]
for a_, b_ in pairs:
    later = equal = earlier = 0; maxlate = 0; late2 = 0; diffs = []
    for key in tables[b_]:
        va, vb = tokval(tables[a_][key]), tokval(tables[b_][key])
        if va > vb:
            later += 1; maxlate = max(maxlate, va - vb); late2 += (va - vb >= 2)
            diffs.append([key[0], key[1], key[2], tables[b_][key], tables[a_][key]])
        elif va == vb:
            equal += 1
        else:
            earlier += 1; diffs.append([key[0], key[1], key[2], tables[b_][key], tables[a_][key]])
    comp[f"{a_}_vs_{b_}"] = {"entries": later + equal + earlier, "later": later, "equal": equal,
                            "earlier": earlier, "max_lateness": maxlate, "later_by_2_or_more": late2,
                            "differing_entries": diffs}
out["threshold_table_comparisons"] = comp
tok = {}
for name, tb in tables.items():
    vals = [tokval(v) for v in tb.values()]
    tok[name] = {"entries": len(vals), "le2_tokens": sum(1 for v in tb.values() if v == "D* <= 2"),
                 "nocross_tokens": sum(1 for v in tb.values() if v == "no crossing at D <= 64"),
                 "m_with_le2": sorted({k_[2] for k_, v in tb.items() if v == "D* <= 2"}),
                 "largest_entry": max(vals)}
out["threshold_table_tokens"] = tok
# the four scored cells at m* = 12 under every pair, and D*real_B gaps to the next integer
sc = {}
for name, tb in tables.items():
    sc[name] = {f"{c}|{rd}": tb[(c, rd, 12)] for c in ("K-571", "B-571") for rd in ("R-B", "R-M")}
out["scored_cells_m12"] = sc
# minimum distance of D*real_B to an integer boundary over the table, per pair: how close any
# R-B entry is to flipping between P forms
gaps = {}
for kr in KRS:
    for pf in PFS:
        best = None
        for c in ("K-571", "B-571"):
            for m in range(2, 31):
                v = dreal[(kr, pf, c, m)]
                d = v - mp.floor(v)
                if best is None or d < best[0]:
                    best = (d, c, m, v)
        gaps[f"{kr}_{pf}"] = {"min_frac_part_of_DrealB": mp.nstr(best[0], 6), "at": [best[1], best[2]],
                              "DrealB": mp.nstr(best[3], 10)}
out["DrealB_fractional_part_minimum"] = gaps
# full tables, compact
out["threshold_tables"] = {name: {f"{k_[0]}|{k_[1]}|{k_[2]}": v for k_, v in tb.items()} for name, tb in tables.items()}
out["DrealB"] = {f"{k_[0]}_{k_[1]}|{k_[2]}|{k_[3]}": mp.nstr(v, 8) for k_, v in dreal.items()}

print(json.dumps(out, indent=1, default=str))

