#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6) supplementary sweep, the validator's own code.
(1) MI-2 at every claim-(A) degree: C_I under both P forms and both k readings,
    with argmin, runner-up and gap; ties detected in exact-ish arithmetic.
(2) G4 margins (D = 4, omega 3, MI-1) under PF-2 and PF-1 against rho from the
    primary inputs (FIPS 186-4 D.1.3; Certicom 2009 Appendix A).
(3) MI-1 direction under PF-1 over the 435 claim-(A) cells.
(4) Read-only comparison with the frozen instrument (V4B-4: importing the frozen
    instrument read-only for comparison is allowed and recorded). PF-2 only:
    the instrument has no PF-1 law.
"""
import json, sys, math, importlib.util, hashlib
sys.path.insert(0, "/tmp/claude-0/-home-user/f42055f8-3588-569d-b7d9-926d696d2468/scratchpad/BATCH-bc5bd5/TASK-20261002-aeaf93")
import mpmath as mp
from fractions import Fraction

mp.mp.dps = 60
LOG2 = mp.log(2)
def log2(v): return mp.log(v) / LOG2
def kval(n, m, kr): return Fraction(n, m) if kr == "MI1" else Fraction(-(-n // m))
def A(n, m, kr, pf):
    k = kval(n, m, kr); e = m * k - n
    x = mp.mpf(2) ** int(e) / mp.mpf(math.factorial(m))
    P = x if pf == "PF1" else -mp.expm1(-x)
    return mp.mpf(k.numerator) / k.denominator - log2(P)
def stage1(n, m, kr, pf, omega=3.0): return A(n, m, kr, pf) + 4 * mp.mpf(omega) * log2(n)
def CI(n, kr, pf, omega=3.0):
    vals = [(m, stage1(n, m, kr, pf, omega)) for m in range(2, min(30, n) + 1)]
    best = None
    for m, v in vals:
        if best is None or v < best[1]: best = (m, v)
    rest = sorted([t for t in vals if t[0] != best[0]], key=lambda t: (t[1], t[0]))
    return {"v": best[1], "m": best[0], "ru": rest[0][0], "gap": rest[0][1] - best[1]}

DEG = [79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]
out = {}
sweep = {}; maxmove = {"MI1": (0, None), "CEIL": (0, None)}; ge001 = []; ties = []; ru_changes = []; am_changes = []
for n in DEG:
    row = {}
    for kr in ("MI1", "CEIL"):
        c2 = CI(n, kr, "PF2"); c1 = CI(n, kr, "PF1")
        mv = c1["v"] - c2["v"]
        row[kr] = {"PF2": [float(mp.nstr(c2["v"], 12)), c2["m"], c2["ru"], mp.nstr(c2["gap"], 6)],
                   "PF1": [float(mp.nstr(c1["v"], 12)), c1["m"], c1["ru"], mp.nstr(c1["gap"], 6)],
                   "move_PF1_minus_PF2": mp.nstr(mv, 6)}
        if abs(mv) > maxmove[kr][0]: maxmove[kr] = (float(abs(mv)), n)
        if abs(mv) >= 0.01: ge001.append([n, kr, mp.nstr(mv, 6), c2["m"], c1["m"]])
        if c1["m"] != c2["m"]: am_changes.append([n, kr, c2["m"], c1["m"]])
        if c1["ru"] != c2["ru"]: ru_changes.append([n, kr, "PF2 ru", c2["ru"], mp.nstr(c2["gap"], 6), "PF1 ru", c1["ru"], mp.nstr(c1["gap"], 6)])
        for pf, c in (("PF2", c2), ("PF1", c1)):
            if abs(c["gap"]) < mp.mpf("1e-40"):
                ties.append([n, kr, pf, c["m"], c["ru"], mp.nstr(c["gap"], 3)])
    sweep[n] = row
out["claimA_sweep"] = sweep
out["max_abs_move"] = maxmove
out["moves_ge_0.01_bit"] = ge001
out["argmin_changes"] = am_changes
out["runner_up_changes"] = ru_changes
out["exact_ties"] = ties

# ---- (2) G4 margins under both P forms (MI-1, D = 4, omega 3)
FIPS = "/home/user/crypto-autoresearcher/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"
CERT = "/home/user/crypto-autoresearcher/inputs/CERTICOM-CHALLENGE-2009/challenge-2009_text.md"
fl = open(FIPS, encoding="utf-8").read().split("\n")
cl = open(CERT, encoding="utf-8").read().split("\n")
def digits(lines, a, b):
    s = "".join(lines[a - 1:b]); s = s.split("=", 1)[1] if "=" in s else s
    return int("".join(ch for ch in s if ch.isdigit()))
def hexn(lines, ln):
    s = lines[ln - 1]; assert s.startswith("n = "), s
    return int(s[4:].replace(" ", ""), 16)
curves = {
    "K-163": (digits(fl, 6708, 6708), 2, 163, 163, "FIPS 6708 (a = 1 at 6707)"),
    "B-163": (digits(fl, 6726, 6726), 2, 163, 1, "FIPS 6726"),
    "K-233": (digits(fl, 6773, 6774), 4, 233, 233, "FIPS 6773-6774 (a = 0 at 6771)"),
    "B-233": (digits(fl, 6799, 6801), 2, 233, 1, "FIPS 6799-6801"),
    "K-283": (digits(fl, 6852, 6854), 4, 283, 283, "FIPS 6852-6854"),
    "B-283": (digits(fl, 6889, 6891), 2, 283, 1, "FIPS 6887-6891"),
    "ECC2-238": (hexn(cl, 2939), int(cl[2937].split("=")[1], 16), 239, 1, "Certicom 2938-2939"),
    "ECC2K-238": (hexn(cl, 2970), int(cl[2968].split("=")[1], 16), 239, 239, "Certicom 2969-2970 (a = 0, b = 1)"),
}
g4 = {}
for c, (r, h, n, kc, src) in curves.items():
    tr = h * r - (2 ** n + 1)
    rho = 0.5 * log2(mp.pi * r / (4 * kc))
    rec = {"source_lines": src, "bits": r.bit_length(), "h": h, "k_c": kc, "hasse_ok": tr * tr <= 4 * 2 ** n,
           "fermat_3_5": bool(pow(3, r - 1, r) == 1 and pow(5, r - 1, r) == 1), "rho": float(mp.nstr(rho, 10))}
    for pf in ("PF2", "PF1"):
        ci = CI(n, "MI1", pf)
        rec[f"margin_{pf}"] = float(mp.nstr(ci["v"] - rho, 10)); rec[f"m_star_{pf}"] = ci["m"]
    rec["sign_same"] = (rec["margin_PF2"] > 0) == (rec["margin_PF1"] > 0)
    g4[c] = rec
out["G4_margins_MI1_both_P_forms"] = g4

# ---- (3) MI-1 direction under PF-1
b = e = a_ = 0; eq = []
for n in DEG:
    for m in range(2, min(30, n) + 1):
        c = stage1(n, m, "CEIL", "PF1"); u = stage1(n, m, "MI1", "PF1")
        if c < u: b += 1
        elif c == u: e += 1; eq.append([n, m])
        else: a_ += 1
out["MI1_direction_PF1"] = {"cells": b + e + a_, "ceiled_below": b, "equal": e, "above": a_, "equal_cells": eq}

# ---- (4) frozen instrument, read-only import, PF-2 comparison
JB = "/home/user/crypto-autoresearcher/experiments/EXP-SEMBIN-81dc96/code/joint_balance.py"
digest = hashlib.sha256(open(JB, "rb").read()).hexdigest()
spec = importlib.util.spec_from_file_location("jb", JB); jb = importlib.util.module_from_spec(spec)
sys.modules["jb"] = jb; spec.loader.exec_module(jb)
mx = 0.0; cnt = 0
for n in (571, 283, 359):
    for kr, kname in (("MI1", "unceiled"), ("CEIL", "ceiled")):
        mo = jb.Model(solve="block_n4w", k_reading=kname)
        for m in range(2, 31):
            v = jb.stage_costs(n, m, m, mo)[0]
            d = abs(v - float(stage1(n, m, kr, "PF2"))); mx = max(mx, d); cnt += 1
mo = jb.Model(solve="block_n4w", charge_cofactor=True)
fx = {}
for n in (571, 283):
    best = None
    for m in range(2, 31):
        v = jb.stage_costs(n, m, m, mo)[0]
        if best is None or v < best[1]: best = (m, v)
    fx[n] = {"C_I_instrument": best[1], "m_star": best[0]}
out["instrument_compare"] = {"path": JB, "sha256": digest, "matches_sha256_expected": digest == "95a069364e2cacea9de914694fb5cdb1c886929626144edeb8835fced8698f46",
                             "cells_compared_PF2": cnt, "max_abs_diff_vs_validator_PF2": mx, "fixture_C_I_by_instrument": fx,
                             "import_note": "spec_from_file_location + sys.modules['jb'] before exec_module, read-only; main() not called"}
