#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6 D-CARRY): the validator's own reference values for
every J9 / J10 quantity family, from the value-free definitions of
coordination/review/nistbin-20260925-b67954/blind-inputs.yaml (Q1, Q2, Q3) and
coordination/review/nistbin-20261002-f435ab/blind-inputs.yaml (Q1-571, QM, Q3,
QB), evaluated with the validator's own code (mpmath 60 digits, exact integers).
Curve orders from the primary texts by line. No producer code is imported."""
import json, math, sys
from fractions import Fraction
import mpmath as mp

mp.mp.dps = 60
LOG2 = mp.log(2)
def log2(v): return mp.log(v) / LOG2
def kval(n, m, kr): return Fraction(n, m) if kr == "KR-A" else Fraction(-(-n // m))
def A(n, m, kr, pf):
    k = kval(n, m, kr); e = m * k - n
    x = mp.mpf(2) ** int(e) / mp.mpf(math.factorial(m))
    P = x if pf == "PF-1" else -mp.expm1(-x)
    return mp.mpf(k.numerator) / k.denominator - log2(P)
def W(N, D): return log2(mp.mpf(sum(math.comb(N, d) for d in range(D + 1))))
def F(v, d=6): return float(mp.nstr(v, 15))

FIPS = "/home/user/crypto-autoresearcher/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"
CERT = "/home/user/crypto-autoresearcher/inputs/CERTICOM-CHALLENGE-2009/challenge-2009_text.md"
fl = open(FIPS, encoding="utf-8").read().split("\n")
cl = open(CERT, encoding="utf-8").read().split("\n")
def dec(lines, a, b):
    s = "".join(lines[a - 1:b]); s = s.split("=", 1)[1] if "=" in s else s
    return int("".join(ch for ch in s if ch.isdigit()))
def hx(lines, nums):
    s = "".join(lines[i - 1] for i in nums); s = s.split("=", 1)[1] if "=" in s else s
    return int(s.replace(" ", ""), 16)
rows = {
    "K-571": (dec(fl, 7023, 7029), 4, 571, 571), "B-571": (dec(fl, 7060, 7066), 2, 571, 1),
    "K-283": (dec(fl, 6852, 6854), 4, 283, 283), "B-283": (dec(fl, 6887, 6891), 2, 283, 1),
    "ECC2-79": (hx(cl, [2599]), 2, 79, 1), "ECC2-89": (hx(cl, [2628]), 2, 89, 1),
    "ECC2-353": (hx(cl, [3029, 3031]), 0x4C, 359, 1), "ECC2K-358": (hx(cl, [3113, 3115]), 2, 359, 359),
}
out = {"Q1": {}}
for c, (r, h, n, kc) in rows.items():
    tr = h * r - (2 ** n + 1)
    others = [hh for hh in range(1, 200) if (hh * r - (2 ** n + 1)) ** 2 <= 4 * 2 ** n]
    out["Q1"][c] = {"n": n, "bits": r.bit_length(), "h": h, "k_c": kc, "hasse_ok": tr * tr <= 4 * 2 ** n,
                    "h_values_in_hasse_1_to_199": others, "fermat_3_5": bool(pow(3, r - 1, r) == 1 and pow(5, r - 1, r) == 1),
                    "log2_r": F(log2(r)), "rho": F(0.5 * log2(mp.pi * r / (4 * kc)))}

# Q2: first minimum over m in 2..30 (declared grid) and over 2..60 (J9 PIN-M-RANGE)
out["Q2"] = {}
for n in (571, 283, 359):
    for kr in ("KR-A", "KR-B"):
        for pf in ("PF-2", "PF-1"):
            for mh in (30, 60):
                best = None
                for m in range(2, min(mh, n) + 1):
                    v = A(n, m, kr, pf) + 12 * log2(n)
                    if best is None or v < best[1]: best = (m, v)
                out["Q2"][f"{n}|{kr}|{pf}|m<= {mh}"] = {"C_I": F(best[1]), "argmin": best[0], "interior": best[0] < min(mh, n)}

# QM at D = 4 over (n, m), both k readings
out["QM_D4"] = {}
for n in (571, 283, 359, 409):
    for m in range(2, 31):
        for kr in ("KR-A", "KR-B"):
            k = kval(n, m, kr)
            N5x = m * k + (m - 2) * n
            N5r = int(round(N5x)); N5c = math.ceil(N5x)
            l = -(-n // m); nvar = m * l
            out["QM_D4"][f"{n}|{m}|{kr}"] = {
                "store": F(mp.mpf(k.numerator) / k.denominator), "N5_exact": str(N5x), "N5_round": N5r, "N5_ceil": N5c,
                "MR_B": F(4 * log2(n)), "MR_M": F(W(n, 4)), "MR_C8": F(log2(math.comb(nvar, 4))), "nvar_C8": nvar,
                "MR_F4": F(4 * log2(n * (m - 1))) if m > 1 else None, "MR_MAC": F(W(N5r, 4))}
# QM at 571 over D
out["QM_571_D"] = {D: {"MR_B": F(D * log2(571)), "MR_M": F(W(571, D))} for D in range(2, 65)}
# QB at 571
out["QB"] = {}
L = log2(571)
for m in range(2, 31):
    for kr in ("KR-A", "KR-B"):
        k = kval(571, m, kr); N5 = int(round(m * k + (m - 2) * 571))
        Wv = {D: W(N5, D) for D in range(3, 65)}
        d7 = {D: (Wv[D] - Wv[4]) - (D - 4) * L for D in range(4, 65)}
        dcum = next((D for D in range(5, 65) if d7[D] < 0), "none in 5..64")
        dps = next((D for D in range(5, 65) if Wv[D] - Wv[D - 1] < L), "none in 5..64")
        mx = max(range(4, 65), key=lambda D: (d7[D], -D))
        out["QB"][f"{m}|{kr}"] = {"N5": N5, "D_cum": dcum, "D_ps": dps, "max_DELTA7": F(d7[mx]), "argmax": mx}
# extras printed as memory beside carried figures
out["extras"] = {
    "W_5139_4": F(W(5139, 4)), "4log2_5139": F(4 * log2(5139)), "N5_571_m10_t10_KR-A": str(Fraction(571, 10) * 10 + 8 * 571),
    "MR_B_409_D5": F(5 * log2(409)), "MR_M_409_D5": F(W(409, 5)), "MR_B_571_D12": F(12 * log2(571)), "MR_M_571_D12": F(W(571, 12)),
    "log2_binom_576": {D: F(log2(math.comb(576, D))) for D in (2, 3, 4, 12, 20)},
    "log2_binom_279_4": F(log2(math.comb(279, 4))), "log2_binom_288_4": F(log2(math.comb(288, 4))), "4log2_576": F(4 * log2(576)),
    "store_571_m10_KR-A": 57.1, "log2_571": F(L), "log2_283": F(log2(283)), "log2_359": F(log2(359)), "log2_409": F(log2(409)),
}
print(json.dumps(out, indent=0, default=str))

