#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6 iii, D-CARRY), one script.

Extracts every numeric token from the frozen version-3 specification and from the
version-4 specification (field by field, YAML-flattened), classifies each token
against the validator's own reference values for the J9 and J10 quantity families
(j6_reference.out.json; labels of the two value-free blind-input files), and
(1) pairs version-3 and version-4 fields by path, listing every J9/J10 value that
    version 3 printed with its version-4 status (identical / changed / moved /
    absent);
(2) checks every J9/J10-classified token of the version-4 specification, hypothesis
    version_4 block, audit sheet and worksheet against the reference at its own
    printed precision (near-misses flagged);
(3) pairs every hypothesis field the version_4 in_force_index marks superseded with
    its restatement and diffs their J9/J10 tokens.
Inputs are read from the snapshot commit bytes via files written by the caller."""
import json, re, sys, math, yaml
from collections import defaultdict

S = sys.argv[1]
ref = json.load(open(f"{S}/j6_reference.out.json"))

# --------------------------------------------------------------- reference families
fam = defaultdict(list)          # value -> list of labels
def add(v, label):
    if v is None: return
    fam_list.append((float(v), label))
fam_list = []
for c, d in ref["Q1"].items():
    add(d["rho"], f"Q1 rho {c} (k_c {d['k_c']})")
for k, d in ref["Q2"].items():
    n, kr, pf, mh = k.split("|")
    if mh.strip() == "m<= 30":
        add(d["C_I"], f"Q2 C_I n={n} {kr} {pf} argmin {d['argmin']}")
for k, d in ref["QM_D4"].items():
    n, m, kr = k.split("|")
    add(d["store"], f"QM relation store n={n} m={m} {kr}")
    if kr == "KR-A":
        add(d["MR_C8"], f"QM MR_C8 n={n} m={m} D=4 (nvar {d['nvar_C8']})"); add(2 * d["MR_C8"], f"QM dense C8 n={n} m={m}")
        if d["MR_F4"]: add(d["MR_F4"], f"QM MR_F4 n={n} t={m} D=4"); add(2 * d["MR_F4"], f"QM dense F4 n={n} t={m}")
    add(d["MR_MAC"], f"QM MR_MAC n={n} t={m} {kr} D=4 (N5 {d['N5_round']})"); add(2 * d["MR_MAC"], f"QM dense MAC n={n} t={m} {kr}")
for n in (571, 283, 359, 409):
    d = ref["QM_D4"][f"{n}|12|KR-A"]
    add(d["MR_B"], f"QM MR_B n={n} D=4"); add(d["MR_M"], f"QM MR_M n={n} D=4")
    add(2 * d["MR_B"], f"QM dense B n={n} D=4"); add(2 * d["MR_M"], f"QM dense M n={n} D=4")
for D, d in ref["QM_571_D"].items():
    add(d["MR_B"], f"QM MR_B n=571 D={D}"); add(d["MR_M"], f"QM MR_M n=571 D={D}")
e = ref["extras"]
add(e["MR_B_409_D5"], "QM MR_B n=409 D=5"); add(e["MR_M_409_D5"], "QM MR_M n=409 D=5")
for D, v in e["log2_binom_576"].items(): add(v, f"QM log2 binom(576,{D}) (MR_C8 form, 571 m=12)")
add(e["log2_binom_279_4"], "QM log2 binom(279,4)"); add(e["4log2_576"], "QM 4 log2 576")
fam_list.sort()
vals = [v for v, _ in fam_list]

import bisect
def classify(v, dec):
    tol = 0.5 * 10 ** (-dec) + 1e-12
    lo = bisect.bisect_left(vals, v - 3 * 10 ** (-dec)); hi = bisect.bisect_right(vals, v + 3 * 10 ** (-dec))
    exact, near = [], []
    for i in range(lo, hi):
        rv, lab = fam_list[i]
        if abs(rv - v) <= tol: exact.append((lab, rv))
        elif abs(rv - v) <= 1.5 * 10 ** (-dec): near.append((lab, rv))
    return exact, near

# --------------------------------------------------------------- flatten + tokens
def flatten(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from flatten(v, f"{path}.{k}" if path else str(k))
    elif isinstance(node, list):
        for i, v in enumerate(node):
            tag = v.get("id") if isinstance(v, dict) and isinstance(v.get("id"), str) else (v.get("stage") if isinstance(v, dict) and "stage" in v else i)
            yield from flatten(v, f"{path}[{tag}]")
    else:
        yield path, node

TOK = re.compile(r"(2\^\{?(-?\d+(?:\.\d+)?)\}?)|((?<![\w.\-])-?\d+\.\d+(?:e-?\d+)?(?![\d]))")
def tokens(text):
    out = []
    for mt in TOK.finditer(text):
        if mt.group(1):
            s = mt.group(2); kind = "pow2"
        else:
            s = mt.group(3); kind = "dec"
        if "e" in s: dec = None
        else: dec = len(s.split(".")[1]) if "." in s else 0
        ctx = text[max(0, mt.start() - 70): mt.end() + 30].replace("\n", " ")
        out.append({"tok": mt.group(0), "val": float(s), "dec": dec, "kind": kind, "ctx": ctx})
    return out

def load(path):
    return yaml.safe_load(open(path, encoding="utf-8"))

v3 = dict((p, str(t)) for p, t in flatten(load(f"{S}/v3spec.yaml")))
v4 = dict((p, str(t)) for p, t in flatten(load(f"{S}/v4spec.yaml")))
hyp = load(f"{S}/hyp_v4.yaml")["hypothesis"] if "hypothesis" in load(f"{S}/hyp_v4.yaml") else load(f"{S}/hyp_v4.yaml")
aud = load(f"{S}/audit_v4.yaml"); wks = load(f"{S}/worksheet_v4.yaml")

def j9j10_tokens(fields):
    res = []
    for p, t in fields.items():
        for tk in tokens(t):
            if tk["dec"] is None or tk["dec"] < 2: continue
            ex, nr = classify(abs(tk["val"]), tk["dec"])
            if ex or nr:
                res.append({"path": p, **tk, "exact": [x[0] for x in ex][:4], "near": [(x[0], round(x[1], 6)) for x in nr][:4] if not ex else []})
    return res

r = {"reference_family_size": len(fam_list)}
# (1) version-3 spec J9/J10 tokens and their version-4 status at the same path
t3 = j9j10_tokens(v3)
rows = []
for tk in t3:
    p = tk["path"]
    if p in v4:
        same = tk["tok"] in v4[p]
        status = "identical at same path" if v3[p] == v4[p] else ("token present at same path (field text changed)" if same else "TOKEN NOT AT SAME PATH IN V4")
    else:
        status = "PATH ABSENT IN V4"
    if not status.startswith("identical") and not status.startswith("token present"):
        elsewhere = [q for q, t in v4.items() if tk["tok"] in t]
        tk["v4_elsewhere"] = elsewhere[:5]
    tk["v4_status"] = status
    rows.append(tk)
r["v3_spec_J9J10_tokens"] = len(rows)
r["v3_status_counts"] = {}
for x in rows:
    r["v3_status_counts"][x["v4_status"]] = r["v3_status_counts"].get(x["v4_status"], 0) + 1
r["v3_rows_not_identical"] = [x for x in rows if not x["v4_status"].startswith("identical")]
r["v3_near_miss"] = [x for x in rows if not x["exact"]]
r["v3_rows_all"] = [{"path": x["path"], "tok": x["tok"], "label": x["exact"][:2] or x["near"][:2], "v4": x["v4_status"]} for x in rows]

# (2) every J9/J10 token in version 4 (four files) against the reference
v4files = {"spec": v4, "hyp_version_4": dict(flatten(hyp["version_4"], "version_4")),
           "audit": dict((p, str(t)) for p, t in flatten(aud)), "worksheet": dict((p, str(t)) for p, t in flatten(wks))}
allv4 = {}
for fk, fields in v4files.items():
    fields = {p: str(t) for p, t in fields.items()}
    toks = j9j10_tokens(fields)
    allv4[fk] = {"tokens": len(toks), "near_miss_only": [x for x in toks if not x["exact"]]}
r["v4_reference_check"] = allv4

# (3) hypothesis supersession pairs via in_force_index
idx = hyp["version_4"]["supersedes_for_version_4"]["in_force_index"]
H = dict(flatten(hyp))
H = {p: str(t) for p, t in H.items()}
def get(path):
    # resolve 'version_2.heuristic_assumptions[0].mi_1' style paths against the parsed mapping
    node = hyp
    for part in re.findall(r"[^.\[\]]+|\[\d+\]", path):
        if part.startswith("["):
            i = int(part[1:-1]);
            if not isinstance(node, list) or i >= len(node): return None
            node = node[i]
        else:
            if not isinstance(node, dict) or part not in node: return None
            node = node[part]
    return node
pairs = []; unres = []
for ent in idx:
    if ent.get("status") == "superseded_by_version_4" and ent.get("by"):
        old = get(ent["path"]); new = get(ent["by"])
        if old is None or new is None:
            unres.append(ent); continue
        def toks_of(node):
            txt = json.dumps(node) if not isinstance(node, str) else node
            out = []
            for tk in tokens(txt):
                if tk["dec"] is None or tk["dec"] < 2: continue
                ex, nr = classify(abs(tk["val"]), tk["dec"])
                if ex or nr: out.append((tk["tok"], (ex[0][0] if ex else "NEAR " + nr[0][0])))
            return out
        ot, nt = toks_of(old), toks_of(new)
        missing = [x for x in ot if x[0] not in (json.dumps(new) if not isinstance(new, str) else new)]
        pairs.append({"old": ent["path"], "by": ent["by"], "old_j9j10": len(ot), "new_j9j10": len(nt), "old_tokens_not_in_restatement": missing})
r["hyp_superseded_pairs"] = len(pairs)
r["hyp_pairs_with_old_token_missing_in_restatement"] = [p for p in pairs if p["old_tokens_not_in_restatement"]]
r["hyp_index_entries_unresolved"] = unres[:20]
r["hyp_index_entries_unresolved_count"] = len(unres)
print(json.dumps(r, indent=1, default=str))

