#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6 iii, D-CARRY), count-based field diff, frozen v3 spec ->
v4 spec, for every numeric token (decimals, 2^x, and integer tokens bound to a J9 or
J10 label: argmin m*, N5, nvar, integer relation stores, M7 endpoints). A token whose
count at a field path falls from v3 to v4 is a DIFFERENCE candidate; each is then
classified and located elsewhere in v4. Same-path pairing uses the YAML-flattened
path (list elements keyed by their id or stage)."""
import json, re, sys, yaml
from collections import Counter

S = sys.argv[1]
def flatten(node, path=""):
    if isinstance(node, dict):
        for k, v in node.items():
            yield from flatten(v, f"{path}.{k}" if path else str(k))
    elif isinstance(node, list):
        for i, v in enumerate(node):
            tag = v.get("id") if isinstance(v, dict) and isinstance(v.get("id"), str) else (f"stage{v['stage']}" if isinstance(v, dict) and "stage" in v else i)
            yield from flatten(v, f"{path}[{tag}]")
    else:
        yield path, node

PAT = [
    ("dec", re.compile(r"(?<![\w.\-^{])-?\d+\.\d+(?:e-?\d+)?(?![\d])")),
    ("pow2", re.compile(r"2\^\{?-?\d+(?:\.\d+)?\}?")),
    ("argmin", re.compile(r"m\*\s*(?:=\s*)?\d+|m\s*=\s*t\s*=\s*\d+|t\*\s*=\s*\d+|m_star:\s*\d+|t_star:\s*\d+")),
    ("N5", re.compile(r"N5\s*=\s*\d+|nvar\s*(?:=\s*)?\d+|l\s*=\s*\d+")),
    ("M7", re.compile(r"D_cum\s*=\s*\d+|D_ps\s*=\s*\d+|D\s*>=\s*\d+|crossings\s+\d+\s+to\s+\d+|from\s+\d+\s+on")),
]
def toks(text):
    c = Counter()
    for kind, rx in PAT:
        for mt in rx.finditer(text):
            c[(kind, re.sub(r"\s+", " ", mt.group(0)))] += 1
    return c

def main():
    v3 = {p: str(t) for p, t in flatten(yaml.safe_load(open(f"{S}/v3spec.yaml", encoding="utf-8")))}
    v4 = {p: str(t) for p, t in flatten(yaml.safe_load(open(f"{S}/v4spec.yaml", encoding="utf-8")))}
    v4all = "\n".join(v4.values())
    res = {"v3_fields": len(v3), "v4_fields": len(v4), "v3_fields_absent_in_v4": [p for p in v3 if p not in v4],
           "v4_fields_new": len([p for p in v4 if p not in v3]), "identical_fields": sum(1 for p in v3 if p in v4 and v3[p] == v4[p]),
           "changed_fields": sum(1 for p in v3 if p in v4 and v3[p] != v4[p])}
    dec = []
    tot3 = Counter()
    for p, t in v3.items():
        c3 = toks(t); tot3.update(c3)
        c4 = toks(v4.get(p, ""))
        for k, n3 in c3.items():
            if c4.get(k, 0) < n3:
                where = [q for q, tt in v4.items() if k[1] in tt][:6]
                dec.append({"path": p, "kind": k[0], "tok": k[1], "v3_count": n3, "v4_count_same_path": c4.get(k, 0),
                            "v4_elsewhere": where, "v3_ctx": t[max(0, t.find(k[1]) - 100): t.find(k[1]) + 60].replace("\n", " ")})
    res["v3_token_occurrences_total"] = sum(tot3.values())
    res["v3_token_occurrences_by_kind"] = dict(Counter({k[0]: 0 for k in tot3}) + Counter([k[0] for k in tot3.elements()]))
    res["decreased_at_same_path"] = dec
    print(json.dumps(res, indent=1))


if __name__ == "__main__":
    main()

