#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6 iii, D-CARRY on the logs): value-by-value comparison of the
version-3 CB-2 C-4 output (v3 audit sheet c_all_out_verbatim, sha256 of the text
a5d7214e...) with the version-4 CB-3 C-4 output (v4 relay, sha256 ccbfb41b...), for
every key both print; and of both with the validator's own values (j6_sweep.out.json
claim-(A) sweep under PF-2, j6_core.out.json A(571, m))."""
import json, sys
S = sys.argv[1]
v3 = json.load(open(f"{S}/cb2_v3_c4_output.json"))
v4 = json.load(open(f"{S}/cb3_c4_output.json"))
sw = json.load(open(f"{S}/j6_sweep.out.json"))
core = json.load(open(f"{S}/j6_core.out.json"))
diffs = []; n_cmp = 0
def walk(a, b, path):
    global n_cmp
    if isinstance(a, dict):
        for k, va in a.items():
            kb = k
            if k not in b:
                alt = {"A_MI1": "A_MI1_PF2", "A_ceiled": "A_ceiled_PF2", "ceiled_minus_MI1": "ceiled_minus_MI1_PF2"}.get(k)
                if alt and alt in b: kb = alt
                else:
                    diffs.append([path + "." + k, "KEY ABSENT IN V4", va]); continue
            walk(va, b[kb], path + "." + k)
    elif isinstance(a, list):
        if len(a) != len(b): diffs.append([path, "LIST LENGTH", len(a), len(b)])
        for i, (x, y) in enumerate(zip(a, b)): walk(x, y, f"{path}[{i}]")
    else:
        n_cmp += 1
        if a != b: diffs.append([path, a, b])
common = [k for k in v3 if k in v4]
mapped = {"fixture_points_MI1": "fixture_points_MI1_PF2"}
for k in v3:
    kb = k if k in v4 else mapped.get(k)
    if kb is None: diffs.append([k, "TOP KEY ABSENT IN V4"]); continue
    if k in ("block", "label"): continue
    walk(v3[k], v4[kb], k)
# A_571_summary in v3 is keyed differently; compare explicitly
s3 = v3["A_571_summary"]; s4 = v4["A_571_summary"]["ceiled_minus_MI1_PF-2"]
expl = {"count_ceiled_below_MI1": s4["count_negative"], "count_equal": s4["count_zero"], "count_ceiled_above_MI1": s4["count_positive"],
        "largest_drop": s4["largest_drop"], "smallest_drop": s4["smallest_drop"]}
summ_diff = [[k, s3[k], expl[k]] for k in expl if s3[k] != expl[k]]
diffs = [d for d in diffs if not d[0].startswith("A_571_summary")]
# reference check of the v3 kreading table (PF-2 values) against the validator's sweep
ref_bad = []
for line in v3["kreading_table"]:
    n = str(line["n"]); me = sw["claimA_sweep"][n]
    for lab, kr in (("MI-1", "MI1"), ("ceiled", "CEIL")):
        c = line[lab]; mv = me[kr]["PF2"]
        if abs(c["C_I"] - mv[0]) > 5e-5 + 1e-12 or c["m_star"] != mv[1] or c["runner_up_m"] != mv[2] or abs(c["runner_up_gap"] - float(mv[3])) > 5e-5 + 1e-9:
            ref_bad.append([n, lab, c["C_I"], c["m_star"], c["runner_up_m"], c["runner_up_gap"], mv])
for r in v3["A_571_by_m"]:
    me = next(x for x in core["A_571_by_m"] if x["m"] == r["m"])
    if abs(r["A_MI1"] - me["A_MI1_PF2"]) > 5e-5 or abs(r["A_ceiled"] - me["A_CEIL_PF2"]) > 5e-5 or abs(r["ceiled_minus_MI1"] - me["CEIL_minus_MI1_PF2"]) > 5e-5:
        ref_bad.append(["A571", r, me])
print(json.dumps({"scalars_compared_v3_vs_v4": n_cmp, "differences_v3_vs_v4": diffs, "A_571_summary_differences": summ_diff,
                  "v3_values_not_matching_validator_reference": ref_bad,
                  "v4_keys_not_in_v3": [k for k in v4 if k not in v3 and k not in mapped.values()]}, indent=1))

