#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 supplementary checks (validator's own code, mpmath 60 digits).
(a) Cells of the claim-(A) grid where the ceiled stage-1 cost under the in-force PF-2
    exceeds Semaev's first-order closed form m! 2^(n/m) n^(4 omega) (= MI-1 under PF-1),
    i.e. where the "at most" gloss of MI-1.direction fails once PF-2 is in force.
(b) The n = 79 and n = 163 ceiled cells under both P forms (C-CEIL-A diagnostic).
(c) C-RHOCONV figure at ECC2K-130 from Bailey's l (line 1096).
(d) OBJ-J6-2 coherence: ECC2-191 corrected time-only margin at omega 2.0, MI-1 vs ceiled.
(e) per-m span ratios at m = 2, 12, 30 (N5 / 60) under both k readings.
(f) omega interval within which the frozen fixture passes (MI-1, PF-2 and PF-1).
"""
import json, math
from fractions import Fraction
import mpmath as mp
mp.mp.dps = 60
L2 = mp.log(2)
def log2(v): return mp.log(v) / L2
def kv(n, m, kr): return Fraction(n, m) if kr == "MI1" else Fraction(-(-n // m))
def A(n, m, kr, pf):
    k = kv(n, m, kr); e = m * k - n
    x = mp.mpf(2) ** int(e) / mp.mpf(math.factorial(m))
    P = x if pf == "PF1" else -mp.expm1(-x)
    return mp.mpf(k.numerator) / k.denominator - log2(P)
def CI(n, kr, pf, om=3.0):
    best = None
    for m in range(2, min(30, n) + 1):
        v = A(n, m, kr, pf) + 4 * mp.mpf(om) * log2(n)
        if best is None or v < best[1]: best = (m, v)
    return best
DEG = [79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]
out = {}
fail = []
for n in DEG:
    for m in range(2, min(30, n) + 1):
        d = A(n, m, "CEIL", "PF2") - A(n, m, "MI1", "PF1")
        if d > 0: fail.append([n, m, float(mp.nstr(d, 8))])
out["a_ceiled_PF2_above_first_order_closed_form"] = {"cells": len(fail), "list": fail,
    "at_argmin_cells": [x for x in fail if x[1] == CI(x[0], "CEIL", "PF2")[0]]}
cells = {}
for n in (79, 163):
    for m in range(2, 13):
        cells[f"{n}|{m}"] = {pf: float(mp.nstr(A(n, m, "CEIL", pf) + 12 * log2(n), 12)) for pf in ("PF2", "PF1")}
out["b_ceiled_cells_79_163"] = cells
out["b_exact_tie_163_PF1_m7_m8"] = {"A_m7": str(Fraction(24) - (7 * 24 - 163)) + " + log2(7!)", "A_m8": str(Fraction(21) - (8 * 21 - 163)) + " + log2(8!) = 19 + log2(7!)",
                                    "difference": float(mp.nstr(A(163, 7, "CEIL", "PF1") - A(163, 8, "CEIL", "PF1"), 5))}
l = 680564733841876926932320129493409985129
rho130 = 0.5 * log2(mp.pi * l / (4 * 131))
out["c_C_RHOCONV"] = {"rho_ECC2K130": float(mp.nstr(rho130, 10)), "plus_log2_1.069993": float(mp.nstr(rho130 + log2(mp.mpf("1.069993")), 10)),
                      "abs_diff_vs_60.9": float(mp.nstr(abs(rho130 + log2(mp.mpf("1.069993")) - mp.mpf("60.9")), 6)), "l_bits": l.bit_length()}
CERT = "/home/user/crypto-autoresearcher/inputs/CERTICOM-CHALLENGE-2009/challenge-2009_text.md"
cl = open(CERT, encoding="utf-8").read().split("\n")
blk = cl[2887:2914]
nline = [s for s in blk if s.startswith("n = ")][0]; hline = [s for s in blk if s.startswith("h = ")][0]
r191 = int(nline[4:].replace(" ", ""), 16); h191 = int(hline.split("=")[1], 16)
rho191 = 0.5 * log2(mp.pi * r191 / 4)
mi1 = CI(191, "MI1", "PF2", 2.0); ce = CI(191, "CEIL", "PF2", 2.0)
out["d_ECC2_191_omega2"] = {"r_bits": r191.bit_length(), "h": h191, "hasse_ok": (h191 * r191 - 2 ** 191 - 1) ** 2 <= 4 * 2 ** 191,
                            "rho": float(mp.nstr(rho191, 8)), "margin_MI1_PF2": float(mp.nstr(mi1[1] - rho191, 8)), "m_MI1": mi1[0],
                            "margin_ceiled_PF2": float(mp.nstr(ce[1] - rho191, 8)), "m_ceiled": ce[0]}
sp = {}
for m in (2, 12, 30):
    for kr in ("MI1", "CEIL"):
        N5 = m * kv(571, m, kr) + (m - 2) * 571
        sp[f"m={m}|{kr}"] = {"N5": str(N5), "N5_over_60": round(float(N5) / 60, 2)}
out["e_per_m_span"] = sp
fx = {}
for pf in ("PF2", "PF1"):
    lo, hi = [], []
    for n, tgt in ((571, Fraction(186307, 1000)), (283, Fraction(147649, 1000))):
        m, c3 = CI(n, "MI1", pf, 3.0)
        slope = 4 * log2(n)
        t = mp.mpf(tgt.numerator) / tgt.denominator
        lo.append(3 + (t - mp.mpf("5e-4") - c3) / slope); hi.append(3 + (t + mp.mpf("5e-4") - c3) / slope)
    fx[pf] = {"omega_min": mp.nstr(max(lo), 10), "omega_max": mp.nstr(min(hi), 10)}
out["f_fixture_omega_interval"] = fx
print(json.dumps(out, indent=1, default=str))

