#!/usr/local/bin/python3
"""TASK-20261002-aeaf93 (J6, V4B-9): MI-2's effect on the RT-4 signs. For every curve
of the fifteen claim-(A) degrees (FIPS 186-4 D.1.3 ten curves; Certicom Appendix A
fifteen binary curves, located by the v4 certicom_rows line pointers; Oakley groups 3
and 4 through rho_ub), the corrected time-only margin C_I(n, omega) - rho at each grid
omega in {3.0, 2.807, 2.376, 2.0}, under MI-1 with PF-2 and with PF-1. Orders and
cofactors from the primary texts; each validated by Hasse and a Fermat test.
Reports the minimum |margin| under PF-2, any sign difference PF-1 vs PF-2, and the
PF-2 signs per degree for comparison with routing.rt4_expectation_table."""
import json, math, re
from fractions import Fraction
import mpmath as mp
mp.mp.dps = 60
L2 = mp.log(2)
def log2(v): return mp.log(v) / L2
def A(n, m, pf):
    x = mp.mpf(1) / mp.mpf(math.factorial(m))          # MI-1: m k - n = 0
    P = x if pf == "PF1" else -mp.expm1(-x)
    return mp.mpf(n) / m - log2(P)
def CI(n, pf, om):
    return min(A(n, m, pf) + 4 * mp.mpf(om) * log2(n) for m in range(2, min(30, n) + 1))
FIPS = "/home/user/crypto-autoresearcher/inputs/FIPS186-4-BINARY-CURVES/fips186-4_text.md"
CERT = "/home/user/crypto-autoresearcher/inputs/CERTICOM-CHALLENGE-2009/challenge-2009_text.md"
fl = open(FIPS, encoding="utf-8").read().split("\n"); cl = open(CERT, encoding="utf-8").read().split("\n")
def dec(a, b):
    s = "".join(fl[a - 1:b]); s = s.split("=", 1)[1] if "=" in s else s
    return int("".join(ch for ch in s if ch.isdigit()))
curves = {  # name: (n, r, h, k_c)
    "K-163": (163, dec(6708, 6708), 2, 163), "B-163": (163, dec(6726, 6726), 2, 1),
    "K-233": (233, dec(6773, 6774), 4, 233), "B-233": (233, dec(6799, 6801), 2, 1),
    "K-283": (283, dec(6852, 6854), 4, 283), "B-283": (283, dec(6887, 6891), 2, 1),
    "K-409": (409, dec(6932, 6936), 4, 409), "B-409": (409, dec(6967, 6971), 2, 1),
    "K-571": (571, dec(7023, 7029), 4, 571), "B-571": (571, dec(7060, 7066), 2, 1)}
rows = [("ECC2-79", 79, 2577, 2605, 1), ("ECC2-89", 89, 2609, 2637, 1), ("ECC2-97", 97, 2641, 2667, 1),
        ("ECC2K-95", 97, 2670, 2697, 97), ("ECC2-109", 109, 2703, 2728, 1), ("ECC2K-108", 109, 2733, 2758, 109),
        ("ECC2-131", 131, 2762, 2790, 1), ("ECC2K-130", 131, 2794, 2819, 131), ("ECC2-163", 163, 2828, 2853, 1),
        ("ECC2K-163", 163, 2856, 2884, 163), ("ECC2-191", 191, 2888, 2913, 1), ("ECC2-238", 239, 2917, 2945, 1),
        ("ECC2K-238", 239, 2949, 2976, 239), ("ECC2-353", 359, 2980, 3058, 1), ("ECC2K-358", 359, 3062, 3115, 359)]
parse_notes = {}
for name, n, a, b, kc in rows:
    blk = cl[a - 1:b]
    hval = None; nhex = None
    for i, s in enumerate(blk):
        st = s.strip()
        if st.startswith("h =") and st[3:].strip():
            hval = int(st[3:].strip(), 16)
        if st.startswith("n ="):
            parts = [st[3:].strip()]
            for t in blk[i + 1:]:
                tt = t.strip()
                if not tt: continue
                if "=" in tt: break
                if re.fullmatch(r"[0-9A-F ]+", tt) and len(tt.replace(" ", "")) >= 8: parts.append(tt)
                else: break
            nhex = "".join(p.replace(" ", "") for p in parts)
    if name == "ECC2K-358":     # reading CR-3: the cofactor token "02" is displaced before the empty "h ="
        hval = 2; parse_notes[name] = "h = 2 per reading CR-3 (token at line 3108), uniqueness checked below"
    r = int(nhex, 16)
    curves[name] = (n, r, hval, kc)
out = {"curves": {}}
for c, (n, r, h, kc) in curves.items():
    tr = h * r - (2 ** n + 1)
    hs = [hh for hh in range(1, 300) if (hh * r - 2 ** n - 1) ** 2 <= 4 * 2 ** n]
    out["curves"][c] = {"n": n, "r_bits": r.bit_length(), "h": h, "k_c": kc, "hasse_ok": tr * tr <= 4 * 2 ** n,
                        "h_unique_in_hasse": hs == [h], "fermat_3_5": bool(pow(3, r - 1, r) == 1 and pow(5, r - 1, r) == 1),
                        "rho": float(mp.nstr(0.5 * log2(mp.pi * r / (4 * kc)), 10))}
for n in (155, 185):   # Oakley groups 3 and 4: rho_ub (IR-3), h >= 2, k = 1
    out["curves"][f"Oakley-{n}"] = {"n": n, "rho_ub": True, "rho": float(mp.nstr(0.5 * log2(mp.pi * (2 ** n + 1 + mp.sqrt(mp.mpf(2) ** (n + 2))) / 8), 10))}
OM = [3.0, 2.807, 2.376, 2.0]
signs = {}; minabs = (1e9, None); flips = []
ci = {}
for c, d in out["curves"].items():
    n = d["n"]
    for om in OM:
        for pf in ("PF2", "PF1"):
            if (n, pf, om) not in ci: ci[(n, pf, om)] = CI(n, pf, om)
        m2 = ci[(n, "PF2", om)] - d["rho"]; m1 = ci[(n, "PF1", om)] - d["rho"]
        if abs(m2) < minabs[0]: minabs = (float(abs(m2)), [c, om, float(mp.nstr(m2, 8))])
        if (m2 > 0) != (m1 > 0): flips.append([c, om, float(m2), float(m1)])
        signs.setdefault(str(n), {}).setdefault(c, []).append("+" if m2 > 0 else "-")
deg_signs = {}
for n, cs in signs.items():
    deg_signs[n] = ["+" if all(v[i] == "+" for v in cs.values()) else ("-" if all(v[i] == "-" for v in cs.values()) else "mixed") for i in range(4)]
out["omega_order"] = OM
out["min_abs_margin_PF2"] = minabs
out["sign_flips_PF1_vs_PF2"] = flips
out["max_PF_move_at_any_degree_MI1_bits"] = max(float(ci[(n, "PF2", 3.0)] - ci[(n, "PF1", 3.0)]) for (n, pf, om) in ci if om == 3.0)
out["per_degree_signs_PF2_all_curves"] = deg_signs
out["per_curve_signs_PF2"] = signs
out["parse_notes"] = parse_notes
print(json.dumps(out, indent=1, default=str))

